+	 *     row.setField(0, "hello");
+	 *     row.setField(1, true);
+	 *     row.setField(2, 1L);
+	 * </pre>
+	 *
+	 */
+	public static Row of(Object... values) {
+		Row row = new Row(values.length);
+		for (int i = 0; i < values.length; i++) {
