+                "when\n" +
+                "    Applicant(age != 1 && < 10 && > 5)\n" +
+                "then\n" +
+                "end";
+
+        addModelField("org.test.Applicant",
+                      "this",
+                      "org.test.Applicant",
+                      DataType.TYPE_THIS);
+        addModelField("org.test.Applicant",
+                      "age",
+                      Integer.class.getName(),
+                      DataType.TYPE_NUMERIC_INTEGER);
+
+        when(dmo.getPackageName()).thenReturn("org.test");
+
+        RuleModel m = RuleModelDRLPersistenceImpl.getInstance().unmarshal(drl,
+                                                                          Collections.emptyList(),
+                                                                          dmo);
+
+        assertNotNull(m);
+        assertEquals("rule1",
+                     m.name);
+
+        assertEquals(1,
+                     m.lhs.length);
+        IPattern p = m.lhs[0];
+        assertTrue(p instanceof FactPattern);
+
+        FactPattern fp = (FactPattern) p;
+        assertEquals("Applicant",
+                     fp.getFactType());
+
+        assertEquals(1,
+                     fp.getConstraintList().getConstraints().length);
+        assertTrue(fp.getConstraint(0) instanceof SingleFieldConstraint);
+
+        SingleFieldConstraint sfp = (SingleFieldConstraint) fp.getConstraint(0);
+        assertEquals("Applicant",
+                     sfp.getFactType());
+        assertEquals("age",
+                     sfp.getFieldName());
+        assertEquals("!=",
+                     sfp.getOperator());
+        assertEquals("1",
+                     sfp.getValue());
+        assertEquals(BaseSingleFieldConstraint.TYPE_LITERAL,
+                     sfp.getConstraintValueType());
+
+        assertEquals(2,
+                     sfp.getConnectives().length);
+        ConnectiveConstraint cc1 = sfp.getConnectives()[0];
+        assertEquals("Applicant",
+                     cc1.getFactType());
+        assertEquals("age",
+                     cc1.getFieldName());
+        assertEquals("&& <",
+                     cc1.getOperator());
+        assertEquals("10",
+                     cc1.getValue());
+        assertEquals(BaseSingleFieldConstraint.TYPE_LITERAL,
+                     cc1.getConstraintValueType());
