+                            Collectors.mapping(jobPairs -> jobPairs.second, Collectors.toList())));
+            // find labels to remove
+            for (List<LoadJob> jobs : tableToLoadJobs.values()) {
+                if (jobs.size() <= Config.cloud_max_copy_job_per_table) {
+                    continue;
