+                long dbId = entry.getKey();
+                if (!dbIdToLabelToLoadJobs.containsKey(dbId)) {
+                    continue;
+                }
+                Map<String, List<LoadJob>> labelToJob = dbIdToLabelToLoadJobs.get(dbId);
